def make_json():
    import json, pathlib
    d = pathlib.Path(__file__).resolve().parent
    ko = json.loads((d / 'ko.json').read_text())
    assert len(ko) == len(T), (len(ko), len(T))
    for i, (k, (e, j)) in enumerate(zip(ko, T)):
        assert k.count('<br/>') == e.count('<br/>') == j.count('<br/>'), (i, k)
    (d / 'en.json').write_text(json.dumps({k: e for k, (e, j) in zip(ko, T)}, ensure_ascii=False, indent=1))
    (d / 'ja.json').write_text(json.dumps({k: j for k, (e, j) in zip(ko, T)}, ensure_ascii=False, indent=1))
    print('en.json, ja.json', len(T))

if __name__ == '__main__':
    make_json()
